export interface DemoActor {
  userId: string;
  tenantId: string;
  role: 'tenant-user' | 'approver';
}

export class HttpError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}

export const requireActor = (
  request: Request,
  role: DemoActor['role'],
): DemoActor => {
  if (request.headers.get('x-demo-role') !== role) {
    throw new HttpError(403, `${role} access is required.`);
  }
  return {
    userId: role === 'approver' ? 'demo_approver' : 'demo_tenant_user',
    tenantId: 'tenant_demo',
    role,
  };
};

import { getHookByToken, resumeHook } from 'workflow/api';
import {
  createApprovalHookToken,
  requireAutomationOwner,
} from './automation-identity.js';
import {
  createRunResolutions,
  isApprovalHookMetadata,
  type ApprovalBatch,
  type ApprovalDecision,
} from '../domain/types.js';
import { HttpError, requireActor } from './auth.js';
import { readBoundedJson } from './read-bounded-json.js';

const parseDecisions = (value: unknown): ApprovalDecision[] => {
  if (!Array.isArray(value))
    throw new HttpError(400, 'decisions must be an array.');
  return value.map(item => {
    if (typeof item !== 'object' || item === null) {
      throw new HttpError(400, 'Each decision must be an object.');
    }
    const candidate = item as Partial<ApprovalDecision>;
    if (
      typeof candidate.interruptionId !== 'string' ||
      typeof candidate.approved !== 'boolean'
    ) {
      throw new HttpError(400, 'Decision fields are invalid.');
    }
    return {
      interruptionId: candidate.interruptionId,
      approved: candidate.approved,
    };
  });
};

export const submitDecision = async (
  request: Request,
  automationId: string,
): Promise<Response> => {
  const actor = requireActor(request, 'approver');
  const { automationKey, runId } = requireAutomationOwner(
    automationId,
    actor.tenantId,
  );
  const body = await readBoundedJson<{ decisions?: unknown }>(
    request,
    64 * 1024,
  );
  const token = [REDACTED];
  const hook = await getHookByToken(token);
  const metadata: unknown = hook.metadata;

  if (
    !isApprovalHookMetadata(metadata) ||
    metadata.automationKey !== automationKey ||
    metadata.tenantId !== actor.tenantId ||
    hook.runId !== runId
  ) {
    throw new HttpError(403, 'You cannot approve this automation.');
  }

  const batch: ApprovalBatch = {
    decisions: parseDecisions(body.decisions),
    decidedBy: actor.userId,
  };

  try {
    createRunResolutions(metadata.requests, batch);
  } catch (error) {
    throw new HttpError(
      400,
      error instanceof Error ? error.message : 'Decision batch is invalid.',
    );
  }

  await resumeHook(token, batch);
  return Response.json({ accepted: true, runId: hook.runId });
};

import { describe, expect, it } from 'vitest';
import { RunDetachedBridgeRequestError } from './errors.js';
import { getHostFunctionContext, run } from './index.js';
import type { HostFunctions } from './index.js';
import { serializeRunValue } from './utils/serde.js';

async function value(
  source: string,
  hostFunctions?: HostFunctions,
): Promise<unknown> {
  const result = await run({
    source,
    ...(hostFunctions === undefined ? {} : { hostFunctions }),
  });
  if (result.status !== 'completed') {
    throw new Error('Unexpected interruption.');
  }
  return result.value;
}

function expectValue(source: string, hostFunctions?: HostFunctions) {
  return expect(value(source, hostFunctions));
}

const LOCKED_GUEST_GLOBALS = [
  'BigInt64Array',
  'BigUint64Array',
  'FinalizationRegistry',
  'Float16Array',
  'InternalError',
  'Iterator',
  'JSON',
  'Math',
  'Promise',
  'Proxy',
  'Reflect',
  'Symbol',
  'WeakRef',
  'console',
  'globalThis',
] as const;

describe('guest sandbox hardening', () => {
  it('exposes only the reviewed global surface', async () => {
    await expectValue(
      'return Object.getOwnPropertyNames(globalThis).sort();',
    ).resolves.toEqual([
      'AggregateError',
      'Array',
      'ArrayBuffer',
      'BigInt',
      'BigInt64Array',
      'BigUint64Array',
      'Boolean',
      'DataView',
      'Date',
      'Error',
      'EvalError',
      'FinalizationRegistry',
      'Float16Array',
      'Float32Array',
      'Float64Array',
      'Function',
      'Infinity',
      'Int16Array',
      'Int32Array',
      'Int8Array',
      'InternalError',
      'Iterator',
      'JSON',
      'Map',
      'Math',
      'NaN',
      'Number',
      'Object',
      'Promise',
      'Proxy',
      'RangeError',
      'ReferenceError',
      'Reflect',
      'RegExp',
      'Set',
      'String',
      'Symbol',
      'SyntaxError',
      'TypeError',
      'URIError',
      'Uint16Array',
      'Uint32Array',
      'Uint8Array',
      'Uint8ClampedArray',
      'WeakMap',
      'WeakRef',
      'WeakSet',
      '__runAssertNoDetachedBridgeCalls',
      '__runCreateBridgePromise',
      '__runSerializeJsonPayload',
      'console',
      'decodeURI',
      'decodeURIComponent',
      'encodeURI',
      'encodeURIComponent',
      'escape',
      'eval',
      'globalThis',
      'isFinite',
      'isNaN',
      'parseFloat',
      'parseInt',
      'undefined',
      'unescape',
    ]);
  });

  it('does not expose ambient host authority or nondeterministic APIs', async () => {
    await expectValue(`
      return Object.fromEntries([
        'process', 'require', 'module', 'Buffer', 'fetch', 'XMLHttpRequest',
        'WebSocket', 'crypto', 'performance', 'setTimeout', 'setInterval',
        'queueMicrotask', 'WebAssembly', 'SharedArrayBuffer', 'Deno', 'Bun'
      ].map(name => [name, typeof globalThis[name]]));
    `).resolves.toEqual({
      Buffer: 'undefined',
      Bun: 'undefined',
      Deno: 'undefined',
      SharedArrayBuffer: 'undefined',
      WebAssembly: 'undefined',
      WebSocket: 'undefined',
      XMLHttpRequest: 'undefined',
      crypto: 'undefined',
      fetch: 'undefined',
      module: 'undefined',
      performance: 'undefined',
      process: 'undefined',
      queueMicrotask: 'undefined',
      require: 'undefined',
      setInterval: 'undefined',
      setTimeout: 'undefined',
    });
  });

  it('blocks the dynamic-code constructor corpus', async () => {
    const results = (await value(`
      const results = [];
      for (const attempt of [
        () => eval('1'),
        () => (0, eval)('1'),
        () => globalThis.eval('1'),
        () => Function('return 1')(),
        () => new Function('return 1')(),
        () => Reflect.construct(Function, ['return 1'])(),
        () => (async function(){}).constructor('return 1')(),
        () => Object.getPrototypeOf(async function(){}).constructor('return 1')(),
        () => (function*(){}).constructor('yield 1')().next(),
        () => Object.getPrototypeOf(function*(){}).constructor('yield 1')().next(),
        () => (async function*(){}).constructor('yield 1')().next(),
        () => Object.getPrototypeOf(async function*(){}).constructor('yield 1')().next(),
        () => (() => {}).constructor('return 1')(),
        () => (function(){}).bind(null).constructor('return 1')(),
        () => (class {}).constructor('return 1')(),
        () => Object.constructor('return 1')(),
        () => Object.getPrototypeOf(Function).constructor('return 1')(),
        () => console.log.constructor('return 1')(),
        () => Object.getPrototypeOf(console.log).constructor('return 1')(),
        () => globalThis.constructor.constructor('return 1')()
      ]) {
        try { attempt(); results.push('allowed'); }
        catch (error) { results.push(String(error.message)); }
      }
      return results;
    `)) as string[];
    expect(results).toHaveLength(20);
    expect(results).not.toContain('allowed');
  });

  it('rejects dynamic module loading', async () => {
    await expect(
      run({ source: "return await import('node:fs');" }),
    ).rejects.toThrow();
  });

  it('freezes builtins, binding proxies, and internal helpers', async () => {
    await expectValue(
      `
      const attempts = [
        () => { Object.prototype.polluted = true; },
        () => { Array.prototype.polluted = true; },
        () => { Promise.prototype.polluted = true; },
        () => { JSON.parse = () => ({ polluted: true }); },
        () => { Math.random = () => 1; },
        () => { Date.now = () => 1; },
        () => { globalThis.Map = function FakeMap() {}; },
        () => { globalThis.Set = function FakeSet() {}; },
        () => { globalThis.__runSerializeJsonPayload = () => '"polluted"'; },
        () => { tools = {}; },
      ];
      for (const attempt of attempts) { try { attempt(); } catch {} }
      return {
        object: Boolean(({}).polluted),
        array: Boolean([].polluted),
        promise: Boolean(Promise.prototype.polluted),
        json: JSON.parse('{"ok":true}'),
        randomWasReplaced: Math.random() === 1,
        dateWasReplaced: Date.now() === 1,
        mapName: Map.name,
        setName: Set.name,
        toolsType: typeof tools,
      };
      `,
      { tools: { ok: () => true } },
    ).resolves.toMatchObject({
      array: false,
      dateWasReplaced: false,
      json: { ok: true },
      mapName: 'Map',
      object: false,
      promise: false,
      randomWasReplaced: false,
      setName: 'Set',
      toolsType: 'function',
    });
  });

  it('uses the captured result serializer after guest global redefinition', async () => {
    const forgedPayload = serializeRunValue(
      new Map([['injectedKey', 'injectedValue']]),
    );

    await expectValue(`
      try {
        Object.defineProperty(globalThis, '__runSerializeJsonPayload', {
          value: () => ${JSON.stringify(forgedPayload)},
          writable: false,
          configurable: false,
        });
      } catch {}
      return 'legitimate result';
    `).resolves.toBe('legitimate result');
  });

  it('uses captured bridge tracking after guest global redefinition', async () => {
    let sideEffects = 0;

    await expect(
      run({
        hostFunctions: {
          tools: {
            sideEffect: () => {
              sideEffects += 1;
            },
          },
        },
        source: `
          try {
            Object.defineProperty(globalThis, '__runCreateBridgePromise', {
              value: (_kind, _name, start) => start(),
              writable: false,
              configurable: false,
            });
          } catch {}
          tools.sideEffect();
          return 'clean';
        `,
      }),
    ).rejects.toBeInstanceOf(RunDetachedBridgeRequestError);
    expect(sideEffects).toBe(0);
  });

  it('locks every privileged guest global binding', async () => {
    const results = (await value(`
      const realmGlobal = globalThis;
      return ${JSON.stringify(LOCKED_GUEST_GLOBALS)}.map(name => {
        const original = realmGlobal[name];
        try { realmGlobal[name] = { replaced: true }; } catch {}
        const descriptor = Object.getOwnPropertyDescriptor(realmGlobal, name);
        return {
          name,
          configurable: descriptor.configurable,
          writable: descriptor.writable,
          unchanged: realmGlobal[name] === original,
        };
      });
    `)) as {
      configurable: boolean;
      name: string;
      unchanged: boolean;
      writable: boolean;
    }[];

    expect(results).toEqual(
      LOCKED_GUEST_GLOBALS.map(name => ({
        configurable: false,
        name,
        unchanged: true,
        writable: false,
      })),
    );
  });

  it('uses trusted intrinsics after attempted guest replacement', async () => {
    await expectValue(
      `
        try { globalThis.Math = { trunc() { throw new Error('fake Math'); } }; } catch {}
        try { globalThis.Promise = { resolve() { throw new Error('fake Promise'); } }; } catch {}
        try { globalThis.Proxy = function FakeProxy() { throw new Error('fake Proxy'); }; } catch {}
        try { globalThis.Reflect = { construct() { throw new Error('fake Reflect'); } }; } catch {}
        try { globalThis.Symbol = { toStringTag: 'then' }; } catch {}

        const explicitDate = new Date(123).getTime();
        const echoed = await tools.echo('ok');
        return { echoed, explicitDate };
      `,
      { tools: { echo: (input: unknown) => input } },
    ).resolves.toEqual({ echoed: 'ok', explicitDate: 123 });
  });

  it('does not invoke guest Error prototype setters for runtime errors', async () => {
    await expect(
      run({
        hostFunctions: { tools: { echo: () => 'ok' } },
        source: `
          for (const name of ['name', 'code', 'details']) {
            Object.defineProperty(Error.prototype, name, {
              configurable: true,
              set() { throw new Error('intercepted ' + name); },
            });
          }
          tools.echo();
          return true;
        `,
      }),
    ).rejects.toBeInstanceOf(RunDetachedBridgeRequestError);
  });

  it('starts with a clean realm after mutation, failure, and interruption', async () => {
    await expectValue(`
      try { Object.prototype.leaked = 'yes'; } catch {}
      try { globalThis.leaked = 'yes'; } catch {}
      return true;
    `).resolves.toBe(true);

    await expect(
      run({ source: "throw new Error('terminal');" }),
    ).rejects.toThrow('terminal');

    const interrupted = await run({
      hostFunctions: {
        tools: {
          pause: () => getHostFunctionContext().interrupt({ kind: 'pause' }),
        },
      },
      source: 'return await tools.pause();',
    });
    expect(interrupted.status).toBe('interrupted');

    await expectValue(`
      return {
        object: ({}).leaked,
        global: globalThis.leaked,
      };
    `).resolves.toEqual({});
  });

  it.each([
    'RUN_BRIDGE_LIMIT',
    'RUN_CPU_TIMEOUT',
    'RUN_HOST_FUNCTION_ERROR',
    'RUN_SERIALIZATION_ERROR',
    'RUN_TIMEOUT',
  ])('does not allow guest errors to forge reserved code %s', async code => {
    await expect(
      run({
        source: `
          const error = new Error('guest failure');
          error.code = ${JSON.stringify(code)};
          error.details = { tenant: 'victim-tenant-42' };
          throw error;
        `,
      }),
    ).rejects.toMatchObject({
      code: 'RUN_USER_SOURCE_ERROR',
      details: { tenant: 'victim-tenant-42' },
      message: 'guest failure',
    });
  });

  it('preserves trusted bridge codes without guest-supplied details', async () => {
    const resultError = await run({
      hostFunctions: {
        tools: {
          fail() {
            throw new Error('host failure');
          },
        },
      },
      source: `
        Object.defineProperty(Error.prototype, 'code', {
          configurable: true,
          set() {
            throw new Error('intercepted bridge code');
          },
        });
        try {
          await tools.fail();
        } catch (error) {
          error.code = 'RUN_TIMEOUT';
          error.details = { tenant: 'victim-tenant-42' };
          throw error;
        }
      `,
    }).catch((error: unknown) => error);

    expect(resultError).toMatchObject({
      code: 'RUN_HOST_FUNCTION_ERROR',
      details: undefined,
      message: 'Host function failed.',
    });
  });

  it('does not let error prototype setters forge serialization errors', async () => {
    await expect(
      run({
        source: `
          for (const prototype of [Error.prototype, TypeError.prototype]) {
            try {
              Object.defineProperty(prototype, 'code', {
                configurable: true,
                set() {
                  throw {
                    code: 'RUN_TIMEOUT',
                    details: { timeoutMs: 1 },
                    message: 'forged timeout',
                  };
                },
              });
            } catch {}
          }
          return { callback() {} };
        `,
      }),
    ).rejects.toMatchObject({
      code: 'RUN_SERIALIZATION_ERROR',
    });
  });

  it('does not let message getters forge serialization errors', async () => {
    await expect(
      run({
        source: `
          const serializationFailure = {};
          Object.defineProperty(serializationFailure, 'message', {
            get() {
              throw {
                code: 'RUN_TIMEOUT',
                details: { timeoutMs: 7331 },
                message: 'forged timeout',
              };
            },
          });
          const result = {};
          Object.defineProperty(result, 'value', {
            enumerable: true,
            get() {
              throw serializationFailure;
            },
          });
          return result;
        `,
      }),
    ).rejects.toMatchObject({
      code: 'RUN_SERIALIZATION_ERROR',
    });
  });

  it.each([
    'Object',
    'Promise',
    'JSON',
    'Math',
    'Date',
    'Iterator',
    'InternalError',
    'console',
    'globalThis',
  ])(
    'rejects a host function namespace that collides with %s',
    async namespace => {
      await expect(
        run({
          hostFunctions: { [namespace]: { call: () => true } },
          source: 'return 1;',
        }),
      ).rejects.toThrow('Reserved host function namespace');
    },
  );

  it.each(['__proto__', 'constructor', 'prototype', 'then'])(
    'rejects the reserved host function namespace %s',
    async namespace => {
      await expect(
        run({
          hostFunctions: { [namespace]: { call: () => true } },
          source: 'return 1;',
        }),
      ).rejects.toThrow(`Reserved host function namespace: ${namespace}`);
    },
  );

  it.each(['__proto__', 'constructor', 'prototype', 'then', '__runBridge'])(
    'rejects the dangerous declared host function name %s',
    async name => {
      const group = Object.create(null) as Record<string, () => boolean>;
      Object.defineProperty(group, name, {
        enumerable: true,
        value: () => true,
      });
      await expect(
        run({ hostFunctions: { tools: group }, source: 'return 1;' }),
      ).rejects.toThrow('Invalid host function name');
    },
  );

  it.each(['hidden', 'admin.reset'])(
    'rejects the non-enumerable host function %s',
    async name => {
      let called = false;
      const group = { visible: () => true };
      Object.defineProperty(group, name, {
        value: () => {
          called = true;
        },
      });

      await expect(
        run({
          hostFunctions: { tools: group },
          source: `return await tools[${JSON.stringify(name)}]();`,
        }),
      ).rejects.toThrow(`Host function "tools.${name}" must be enumerable.`);
      expect(called).toBe(false);
    },
  );

  it('rejects a non-enumerable host function namespace', async () => {
    const hostFunctions = {};
    Object.defineProperty(hostFunctions, 'tools', {
      value: { visible: () => true },
    });

    await expect(
      run({ hostFunctions, source: 'return await tools.visible();' }),
    ).rejects.toThrow('Host function namespace "tools" must be enumerable.');
  });

  it('does not expose host functions added after validation', async () => {
    let called = false;
    const group: Record<string, () => unknown> = {};
    group.install = () => {
      group.hidden = () => {
        called = true;
      };
    };

    await expect(
      run({
        hostFunctions: { tools: group },
        source: 'await tools.install(); return await tools.hidden();',
      }),
    ).rejects.toMatchObject({ code: 'RUN_HOST_FUNCTION_ERROR' });
    expect(called).toBe(false);
  });

  it.each([
    '',
    '1call',
    'call-name',
    'call.name',
    'call name',
    'call\nname',
    '\0call',
    'café',
    '🔧',
  ])('rejects the invalid host function name %j', async name => {
    await expect(
      run({
        hostFunctions: { tools: { [name]: () => true } },
        source: 'return 1;',
      }),
    ).rejects.toThrow('Invalid host function name');
  });

  it.each(['call', '_call', '$call', 'call2'])(
    'accepts the valid host function name %s',
    async name => {
      await expectValue(`return await tools[${JSON.stringify(name)}]();`, {
        tools: { [name]: () => true },
      }).resolves.toBe(true);
    },
  );
});

import { describe, expect, it } from 'vitest';
import {
  createApprovalHookToken,
  createAutomationId,
  createAutomationKey,
  requireAutomationOwner,
} from '../src/api/automation-identity.js';
import { completedOutcomeResponse } from '../src/api/get-automation.js';
import {
  MAX_SOURCE_BYTES,
  startAutomation,
} from '../src/api/start-automation.js';

process.env.RUN_CONTINUATION_SECRET =
  '[REDACTED]';

describe('API boundaries', () => {
  it('binds automation IDs to their tenant', () => {
    const automationKey = createAutomationKey();
    const automationId = createAutomationId(
      'tenant_demo',
      automationKey,
      'run_123',
    );
    expect(() =>
      requireAutomationOwner(automationId, 'tenant_demo', 'run_123'),
    ).not.toThrow();
    expect(() => requireAutomationOwner(automationId, 'tenant_other')).toThrow(
      'does not belong',
    );
    expect(() =>
      requireAutomationOwner(automationId, 'tenant_demo', 'run_other'),
    ).toThrow('does not belong');
  });

  it('derives a secret hook token that is not the public automation ID', () => {
    const automationKey = createAutomationKey();
    const automationId = createAutomationId(
      'tenant_demo',
      automationKey,
      'run_123',
    );
    const token = [REDACTED];
    expect(token).toMatch(/^order-approval:/u);
    expect(token).not.toContain(automationId);
  });

  it('rejects oversized source before starting a workflow', async () => {
    const request = new Request('http://localhost/api/automations', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-demo-role': 'tenant-user',
      },
      body: JSON.stringify({ source: 'x'.repeat(MAX_SOURCE_BYTES + 1) }),
    });

    await expect(startAutomation(request)).rejects.toMatchObject({
      status: 413,
    });
  });

  it('reports a terminal Run outcome as failed', async () => {
    const response = completedOutcomeResponse({
      status: 'failed',
      error: { code: 'RUN_ERROR', message: 'Invalid source.' },
    });
    await expect(response.json()).resolves.toEqual({
      status: 'failed',
      error: { code: 'RUN_ERROR', message: 'Invalid source.' },
    });
  });
});

import { describe, expect, it } from 'vitest';
import { assertContinuationState } from './continuation-validation.js';
import type { RunContinuationState } from './types.js';
import { normalizeOptions } from './utils/options.js';

const source = `
  await tools.first({ value: 1 });
  try { await tools.second({ value: 2 }); } catch {}
  return await tools.pause({ value: 3 });
`;
const scopeHash = '02'.repeat(32);

const requireEntry = <T>(values: T[], index: number): T => {
  const value = values[index];
  if (value === undefined) {
    throw new Error(`Missing test ledger entry at index ${index}.`);
  }
  return value;
};

const validState = (): RunContinuationState => ({
  determinism: {
    dateNowMs: 1_700_000_000_000,
    randomSeed: '01'.repeat(16),
  },
  ledger: [
    {
      bindingName: 'tools.first',
      dateNowMs: 1_700_000_000_001,
      inputJson: '[[1],{"value":2},1]',
      settledOrder: 1,
      status: 'fulfilled',
      valueJson: '[true]',
    },
    {
      bindingName: 'tools.second',
      dateNowMs: 1_700_000_000_002,
      error: { message: 'expected', name: 'Error' },
      inputJson: '[[1],{"value":2},2]',
      settledOrder: 2,
      status: 'rejected',
    },
    {
      bindingName: 'tools.pause',
      inputJson: '[[1],{"value":2},3]',
      interruptionId: 'interrupt-3',
      payloadJson: '[{"kind":1},"pause"]',
      status: 'interrupted',
    },
  ],
  logicalRunId: '03'.repeat(16),
  runtime: 'run-replay-v2',
  scopeHash,
  serde: 'run-js-v1',
  source,
  version: 2,
});

const expectInvalid = (value: unknown): void => {
  expect(() =>
    assertContinuationState(value, source, scopeHash, normalizeOptions()),
  ).toThrowError(expect.objectContaining({ code: 'RUN_PROTOCOL_ERROR' }));
};

describe('continuation state validation hardening', () => {
  it('accepts matching optional bridge limits without changing the v2 state', () => {
    const options = normalizeOptions();
    expect(() =>
      assertContinuationState(
        {
          ...validState(),
          bridgeRequestLimits: {
            maxBridgeRequests: options.maxBridgeRequests,
            maxHostFunctionArgumentsBytes: options.maxHostFunctionInputBytes,
          },
        },
        source,
        scopeHash,
        options,
      ),
    ).not.toThrow();
  });

  it.each([
    undefined,
    null,
    {},
    { maxBridgeRequests: 256 },
    {
      extra: true,
      maxBridgeRequests: 256,
      maxHostFunctionArgumentsBytes: 1024 * 1024,
    },
    { maxBridgeRequests: '256', maxHostFunctionArgumentsBytes: 1024 * 1024 },
    { maxBridgeRequests: 1, maxHostFunctionArgumentsBytes: 1024 * 1024 },
    { maxBridgeRequests: 256, maxHostFunctionArgumentsBytes: 64 },
  ])(
    'rejects malformed or mismatched bridge limits %j',
    bridgeRequestLimits => {
      expectInvalid({ ...validState(), bridgeRequestLimits });
    },
  );

  it('validates mixed synchronous, module, and asynchronous ledger entries', () => {
    const state = validState();
    state.ledger = [
      {
        bindingName: 'effects.write',
        bridgeKind: 'sync-host',
        inputJson: '[[1],"value"]',
        status: 'fulfilled',
        valueJson: '[1]',
      },
      {
        bindingName: 'moduleLoader.normalize',
        bridgeKind: 'module-normalize',
        inputJson: '["./value.js","<entry>"]',
        status: 'fulfilled',
        valueJson: '"/value.js"',
      },
      {
        bindingName: 'moduleLoader.load',
        bridgeKind: 'module-load',
        inputJson: '["/value.js"]',
        status: 'fulfilled',
        valueJson: '"export const value = 1;"',
      },
      {
        bindingName: 'tools.pause',
        inputJson: '[[]]',
        interruptionId: 'interrupt-4',
        payloadJson: '["pause"]',
        status: 'interrupted',
      },
    ];
    expect(() =>
      assertContinuationState(state, source, scopeHash, normalizeOptions()),
    ).not.toThrow();

    const malformed = structuredClone(state) as unknown as {
      ledger: Record<string, unknown>[];
    };
    requireEntry(malformed.ledger, 1).inputJson = '["missing-importer"]';
    expectInvalid(malformed);

    const oversized = structuredClone(state) as unknown as {
      ledger: Record<string, unknown>[];
    };
    requireEntry(oversized.ledger, 2).valueJson = JSON.stringify(
      'x'.repeat(33),
    );
    expect(() =>
      assertContinuationState(oversized, source, scopeHash, {
        ...normalizeOptions(),
        maxSourceBytes: 32,
      }),
    ).toThrowError(expect.objectContaining({ code: 'RUN_PROTOCOL_ERROR' }));
  });

  it('accepts only the exact versioned state shape', () => {
    expect(() =>
      assertContinuationState(
        validState(),
        source,
        scopeHash,
        normalizeOptions(),
      ),
    ).not.toThrow();
    for (const mutation of [
      (state: Record<string, unknown>) => {
        state.extra = true;
      },
      (state: Record<string, unknown>) => {
        (state.determinism as Record<string, unknown>).extra = true;
      },
      (state: Record<string, unknown>) => {
        ((state.ledger as unknown[])[0] as Record<string, unknown>).extra =
          true;
      },
    ]) {
      const state = validState() as unknown as Record<string, unknown>;
      mutation(state);
      expectInvalid(state);
    }
  });

  it('rejects uppercase hex random seeds at the validation boundary', () => {
    const lowercaseSeed = validState();
    lowercaseSeed.determinism.randomSeed = 'ab'.repeat(16);
    expect(() =>
      assertContinuationState(
        lowercaseSeed,
        source,
        scopeHash,
        normalizeOptions(),
      ),
    ).not.toThrow();

    const uppercaseSeed = validState();
    uppercaseSeed.determinism.randomSeed = 'AB'.repeat(16);
    expect(() =>
      assertContinuationState(
        uppercaseSeed,
        source,
        scopeHash,
        normalizeOptions(),
      ),
    ).toThrowError('Continuation determinism state is invalid.');
  });

  it('rejects sparse arrays, cycles, accessors, and non-plain objects', () => {
    const sparse = validState();
    sparse.ledger = [];
    sparse.ledger.length = 3;
    sparse.ledger[0] = requireEntry(validState().ledger, 0);
    sparse.ledger[2] = requireEntry(validState().ledger, 2);
    expectInvalid(sparse);

    const cycle = validState() as RunContinuationState & { cycle?: unknown };
    cycle.cycle = cycle;
    expectInvalid(cycle);

    const accessor = validState();
    Object.defineProperty(accessor.determinism, 'randomSeed', {
      get() {
        throw new Error('accessor failure');
      },
    });
    expectInvalid(accessor);

    expectInvalid({ ...validState(), determinism: new Date() });
  });

  it('fails closed for 10,000 structure-aware state mutations', () => {
    let random = 2_738_958_700;
    const next = (): number => {
      random = (random * 1_664_525 + 1_013_904_223) % 4_294_967_296;
      return random;
    };
    const generatedJson = (depth: number): unknown => {
      if (depth > 2) {
        return next() % 2 === 0 ? next() : `v-${next()}`;
      }
      return next() % 2 === 0
        ? Array.from({ length: next() % 4 }, () => generatedJson(depth + 1))
        : { value: generatedJson(depth + 1) };
    };

    for (let iteration = 0; iteration < 10_000; iteration += 1) {
      const state = validState() as unknown as Record<string, unknown>;
      const ledger = state.ledger as Record<string, unknown>[];
      switch (next() % 12) {
        case 0: {
          state.version = next();
          break;
        }
        case 1: {
          state.runtime = `runtime-${next()}`;
          break;
        }
        case 2: {
          state.source = `${source}\n${next()}`;
          break;
        }
        case 3: {
          (state.determinism as Record<string, unknown>).randomSeed =
            `${next()}`;
          break;
        }
        case 4: {
          (state.determinism as Record<string, unknown>).dateNowMs = -1;
          break;
        }
        case 5: {
          requireEntry(ledger, next() % ledger.length).bindingName =
            'constructor';
          break;
        }
        case 6: {
          requireEntry(ledger, next() % ledger.length).inputJson = '{';
          break;
        }
        case 7: {
          requireEntry(ledger, 0).settledOrder = 2;
          break;
        }
        case 8: {
          requireEntry(ledger, 1).error = {
            extra: true,
            message: 'x',
            name: 'Error',
          };
          break;
        }
        case 9: {
          requireEntry(ledger, 2).interruptionId = `interrupt-${next()}`;
          break;
        }
        case 10: {
          requireEntry(ledger, 2).payloadJson = '{';
          break;
        }
        default: {
          requireEntry(ledger, next() % ledger.length).extra = generatedJson(0);
        }
      }
      expectInvalid(state);
    }
  });

  it('enforces exact aggregate state bytes rather than an entry estimate', () => {
    const state = validState();
    const exactBytes = Buffer.byteLength(JSON.stringify(state));
    expect(() =>
      assertContinuationState(state, source, scopeHash, {
        ...normalizeOptions(),
        maxContinuationBytes: exactBytes,
      }),
    ).not.toThrow();
    expect(() =>
      assertContinuationState(state, source, scopeHash, {
        ...normalizeOptions(),
        maxContinuationBytes: exactBytes - 1,
      }),
    ).toThrowError(expect.objectContaining({ code: 'RUN_PROTOCOL_ERROR' }));
  });
});

import { beforeEach, describe, expect, it } from 'vitest';
import { RunSourceTooLargeError } from '../errors.js';
import {
  assertSourceSize,
  clearTransformedSourceCache,
  getTransformedSourceCacheStats,
  transformSource,
} from './source-cache.js';

describe('source limits and transform cache', () => {
  beforeEach(() => {
    clearTransformedSourceCache();
  });

  it('rejects oversized source before type stripping', () => {
    expect(() => assertSourceSize('const value = 1; return value;', 8)).toThrow(
      RunSourceTooLargeError,
    );
  });

  it('allows source exactly at the byte limit', () => {
    const source = 'return 1;';
    const maxSourceBytes = new TextEncoder().encode(source).byteLength;
    expect(() => assertSourceSize(source, maxSourceBytes)).not.toThrow();
  });

  it('strips TypeScript syntax without changing source line count', () => {
    const source = 'const value: number = 1;\nreturn value;';
    const transformed = transformSource(source);
    expect(transformed).not.toContain(': number');
    expect(transformed.split('\n')).toHaveLength(source.split('\n').length);
  });

  it('strips TypeScript syntax from ES module source', () => {
    const source = 'export const value: number = 42;';
    const transformed = transformSource(source, true);
    expect(transformed).not.toContain(': number');
    expect(transformed).toContain('export const value');
  });

  it('falls back when the host transformer rejects deeply nested source', () => {
    const source = `${'('.repeat(1000)}1${')'.repeat(1000)}`;
    expect(() => transformSource(source, true)).not.toThrow();
  });

  it('does not extract Bun transforms that inject external helpers', () => {
    if ((globalThis as { Bun?: unknown }).Bun === undefined) {
      return;
    }

    const source =
      'using resource: Disposable = getResource();\nreturn resource;';
    expect(transformSource(source)).toBe(source);
  });

  it('does not cache transformed sources above the per-entry byte limit', () => {
    const largeSource = `const value = ${JSON.stringify('x'.repeat(70_000))}; return value.length;`;
    transformSource(largeSource);
    expect(getTransformedSourceCacheStats().entries).toBe(0);
  });

  it('evicts transformed source cache entries by total byte size', () => {
    for (let index = 0; index < 90; index += 1) {
      transformSource(
        `const value = ${JSON.stringify(`${index}:${'x'.repeat(60_000)}`)}; return value.length;`,
      );
    }

    const stats = getTransformedSourceCacheStats();
    expect(stats.bytes).toBeLessThanOrEqual(stats.maxBytes);
    expect(stats.entries).toBeLessThan(90);
  });
});

